<?php require __DIR__.'/config.php';try{$branches=db()->query("SELECT branch_name,address,phone,status FROM branches WHERE status <> 'closed' ORDER BY branch_name")->fetchAll();}catch(Throwable $x){$branches=[];$unavailable=true;}render_start('Branches');?><section class="page-heading"><div class="eyebrow dark">A familiar face nearby</div><h1>Find a branch</h1><p>Our branch teams are ready to help with your banking questions.</p></section><?php if(!empty($unavailable)):?><div class="notice error">Branch information is temporarily unavailable. Please try again later.</div><?php elseif(!$branches):?><div class="empty">Branch details will appear here soon.</div><?php else:?><div class="branch-grid"><?php foreach($branches as $b):?><article class="branch-card"><div class="branch-mark">B</div><span class="badge"><?=e(str_replace('_',' ',ucfirst($b['status'])))?></span><h2><?=e($b['branch_name'])?></h2><p><?=e($b['address'])?></p><a href="tel:<?=e(preg_replace('/[^0-9+]/','',$b['phone']))?>"><?=e($b['phone'])?></a></article><?php endforeach;?></div><?php endif;?><?php render_end();?>
